from pathlib import Path
from playwright.sync_api import sync_playwright,expect
B='http://localhost:3002';fp=Path('.tmp-check/stores-fixture.json');f=json.loads(fp.read_text(encoding='utf-8'));accounts=json.loads(Path('.tmp-check/workspace-accounts.json').read_text(encoding='utf-8'))['accounts'];expect.set_options(timeout=30000)
with sync_playwright() as p:
 browser=p.chromium.launch();admin=browser.new_context(base_url=B,extra_http_headers={'Origin':B});a=next(a for a in accounts if a['key']=='navigation');assert admin.request.post('/api/workspace/login',data={'email':a['email'],'password':a['password']}).ok;sid=f['ids'][0];s=admin.request.get('/api/workspace/stores?id='+sid).json()['stores'][0];req=str(uuid.uuid4());r=admin.request.post('/api/workspace/stores',data={'operation':'edit','requestId':req,'expected':s['version'],'data':{**s,'is_active':False}});assert r.ok;r_id=req;f['requests'].append(r_id);fp.write_text(json.dumps(f),encoding='utf-8')
 for key in ['view','create']:
  c=browser.new_context(base_url=B,extra_http_headers={'Origin':B});a=next(a for a in f['actors'] if a['key']==key);assert c.request.post('/api/workspace/login',data={'email':a['email'],'password':a['password']}).ok;r=c.request.get('/api/workspace/stores?inactive=true');assert r.ok and all(x['is_active'] for x in r.json()['stores']);assert c.request.get('/api/workspace/stores?id='+sid).status==404;assert c.request.post('/api/workspace/stores',data={'operation':'edit','requestId':str(uuid.uuid4()),'expected':s['version'],'data':s}).status==403
  if key=='view':assert c.request.post('/api/workspace/stores',data={'operation':'create','requestId':str(uuid.uuid4()),'data':{'store_code':'VWNO'}}).status==403;c.close();continue
